
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_vmt84_ge_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_vmt84_ge", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.243869262948503e+00, -4.161219232288220e+00, -4.045474047449245e+00, -3.885281550196492e+00, -3.667306718752811e+00, -3.377868886386422e+00, -3.006815963755505e+00, -2.554593901301474e+00, -2.042040767865234e+00, -1.515662054785047e+00, -1.024305752932223e+00, -6.945795849507482e-01, -5.966474342602022e-01, -4.892675485141822e-01, -3.533022213607221e-01, -2.274564250227604e-01, -1.304615860592146e-01, -4.863452603507974e-02, -5.710599297421367e-03, -2.529351018354830e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


